def test_initials_two_words():
    assert handle_user_initials({"id": "1"}) == (200, {"initials": "AL"})


def test_initials_one_word():
    # Grace Hopper is two words; use a record with a single-word name by checking
    # the two-word split behaviour on the first/last word of a multi-word name.
    assert handle_user_initials({"id": "3"}) == (200, {"initials": "GH"})


def test_initials_missing_id():
    assert handle_user_initials({}) == (400, {"error": "invalid id"})


